edits.newText:
function findFrequentItemsets(transactions, minSupport) {
  const index = asIndex(transactions);
  const n = index.n;
  if (!(n > 0) || !(minSupport > 0)) return [];
  // count >= ceil(minSupport * n) is equivalent to count / n >= minSupport up
  // to float error; the epsilon keeps exact multiples of n from rounding up.
  const minCount = Math.ceil(minSupport * n - 1e-9);

  const frequent = [];

  // Level 1: frequent single items, sorted so every deeper itemset (built by
  // ordered joins) comes out in canonical lexicographic order.
  let level = [];
  for (const [stock, posting] of index.byStock) {
    if (posting.size >= minCount) {
      level.push([stock]);
      frequent.push({ items: [stock], count: posting.size, support: posting.size / n });
    }
  }
  if (level.length === 0) return frequent;
  level.sort((a, b) => (a[0] < b[0] ? -1 : 1));

  // Level k: join frequent (k-1)-itemsets that share their first k-2 items,
  // prune by downward closure, then count the survivors through the index.
  while (level.length > 0) {
    const previousSet = new Set(level.map((items) => items.join("\u0000")));

    // Group the frequent (k-1)-itemsets by their common prefix (first k-2
    // items); a k-candidate is prefix + [x, y] with x < y from one group.
    const groups = new Map();
    for (const items of level) {
      const prefix = items.slice(0, items.length - 1);
      const key = prefix.join("\u0000");
      const last = items[items.length - 1];
      const group = groups.get(key);
      if (group) group.lasts.push(last);
      else groups.set(key, { prefix, lasts: [last] });
    }

    const next = [];
    for (const { prefix, lasts } of groups.values()) {
      lasts.sort();
      for (let i = 0; i < lasts.length; i++) {
        for (let j = i + 1; j < lasts.length; j++) {
          const candidate = [...prefix, lasts[i], lasts[j]];
          // Downward closure: dropping any one prefix element must leave a
          // frequent (k-1)-subset; the two subsets ending in lasts[i]/lasts[j]
          // are the joins we came from and are frequent by construction.
          let closed = true;
          for (let drop = 0; drop < prefix.length; drop++) {
            const subset = [
              ...prefix.slice(0, drop),
              ...prefix.slice(drop + 1),
              lasts[i],
              lasts[j],
            ].join("\u0000");
            if (!previousSet.has(subset)) {
              closed = false;
              break;
            }
          }
          if (!closed) continue;
          const count = countItemset(index, candidate);
          if (count >= minCount) {
            next.push(candidate);
            frequent.push({ items: candidate, count, support: count / n });
          }
        }
      }
    }
    next.sort((a, b) => (a.join("\u0000") < b.join("\u0000") ? -1 : 1));
    level = next;
  }
  return frequent;
}

