edits.newText:
function generateRules(frequentItemsets, minConfidence) {
  // Count lookup keyed on the sorted stock codes (the miner already emits
  // sorted items, but sort anyway so hand-built itemsets also resolve).
  const byKey = new Map();
  for (const itemset of frequentItemsets) {
    byKey.set([...new Set(itemset.items)].sort().join("\u0000"), itemset);
  }

  const rules = [];
  for (const itemset of frequentItemsets) {
    const items = [...new Set(itemset.items)];
    // 2^items splits per itemset: cap the size so a hand-built monster itemset
    // cannot hang the page (the miner never emits anything this large).
    if (items.length < 2 || items.length > 20) continue;
    // N is not passed in; recover it from the itemset's own support
    // (support = count / N, and support > 0 because minSupport > 0).
    const n = itemset.count / itemset.support;
    const total = 1 << items.length;
    for (let mask = 1; mask < total - 1; mask++) {
      const antecedent = [];
      const consequent = [];
      for (let bit = 0; bit < items.length; bit++) {
        (mask & (1 << bit) ? antecedent : consequent).push(items[bit]);
      }
      const antecedentItemset = byKey.get([...antecedent].sort().join("\u0000"));
      const consequentItemset = byKey.get([...consequent].sort().join("\u0000"));
      if (!antecedentItemset || !consequentItemset) continue;
      const confidence = computeConfidence(itemset.count, antecedentItemset.count);
      if (!confidence.defined || confidence.value < minConfidence) continue;
      const lift = computeLift(confidence, consequentItemset.count, n);
      rules.push({
        antecedent,
        consequent,
        jointCount: itemset.count,
        antecedentCount: antecedentItemset.count,
        consequentCount: consequentItemset.count,
        support: itemset.support,
        confidence: confidence.value,
        lift: lift.value,
      });
    }
  }
  // Deterministic order, strongest association first.
  rules.sort(
    (a, b) =>
      b.lift - a.lift ||
      b.confidence - a.confidence ||
      a.antecedent.join("\u0000").localeCompare(b.antecedent.join("\u0000")) ||
      a.consequent.join("\u0000").localeCompare(b.consequent.join("\u0000")),
  );
  return rules;
}

