  (a, b) =>
    b.lift - a.lift ||
    b.confidence - a.confidence ||
    byString(a.antecedent.join("\u0000"), b.antecedent.join("\u0000")) ||
    byString(a.consequent.join("\u0000"), b.consequent.join("\u0000")),
);
return rules;

